use kernel_core::{api,codec,model::{Expr,Model,Q,Row,Var},proof::*,verify::{verify,verify_with_diagnostics,Diagnostics,Limits}};
fn q(n:i64)->Q{Q::from_integer(n.into())}
fn model()->Model{Model{name:"m".into(),vars:vec![Var{name:"x".into(),integer:true,lower:Some(q(0)),upper:Some(q(1))}],rows:vec![],objective:Expr::var(0)}}
fn identity()->Block{Block{steps:vec![],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::VarLower(0),Ref::VarUpper(0),Ref::VarInt(0),Ref::Exact]}}}
fn certificate()->Certificate{Certificate{forward:identity(),reverse:identity()}}
#[test]fn fixed_identity_and_shared_budget(){let m=model();let c=certificate();let stats=verify(&m,&m,&c,&Limits::default()).unwrap();assert_eq!(stats.obligations,8);verify(&m,&m,&c,&Limits{work:stats.work,..Limits::default()}).unwrap();assert!(verify(&m,&m,&c,&Limits{work:stats.work-1,..Limits::default()}).unwrap_err().starts_with("RESOURCE_LIMIT"));}
#[test]fn dominated_solutions_may_be_deleted(){let s=model();let mut t=s.clone();t.vars[0].upper=Some(q(0));let c=Certificate{forward:Block{steps:vec![],end:End::Return{map:vec![Expr::zero()],checks:vec![Ref::Exact,Ref::Exact,Ref::Exact,Ref::VarLower(0)]}},reverse:Block{steps:vec![Step::Lin{id:0,kind:Kind::Le,constant:q(-1),terms:vec![(Ref::VarUpper(0),q(1))]}],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::VarLower(0),Ref::Local(0),Ref::VarInt(0),Ref::Exact]}}};verify(&s,&t,&c,&Limits::default()).unwrap();}
#[test]fn every_actual_bound_row_integer_and_objective_is_required(){let s=model();for part in 0..6 {let mut t=s.clone();let mut c=certificate();match part{0=>t.vars[0].lower=Some(q(1)),1=>t.vars[0].upper=Some(q(0)),2=>t.objective.constant=q(1),3=>t.rows.push(Row{name:"r".into(),expr:Expr::var(0),lower:None,upper:Some(q(0))}),4=>if let End::Return{checks,..}=&mut c.forward.end{checks.remove(2);},_=>if let End::Return{map,..}=&mut c.forward.end{map.clear();}}assert!(verify(&s,&t,&c,&Limits::default()).is_err(),"{part}");}}
#[test]fn reverse_is_independently_checked_and_located(){let m=model();let mut c=certificate();c.reverse.steps.push(Step::Lin{id:9,kind:Kind::Le,constant:q(1),terms:vec![]});let mut d=Diagnostics::default();assert!(verify_with_diagnostics(&m,&m,&c,&Limits::default(),&mut d).is_err());assert_eq!(d.location.direction,Some("reverse"));assert_eq!(d.location.step,Some(0));}
#[test]fn no_cross_direction_fact_leak(){let m=model();let mut c=certificate();c.forward.steps.push(Step::Lin{id:8,kind:Kind::Le,constant:q(0),terms:vec![(Ref::VarLower(0),q(1))]});if let End::Return{checks,..}=&mut c.reverse.end{checks[0]=Ref::Local(8);}assert!(verify(&m,&m,&c,&Limits::default()).is_err());}

#[test]fn unboundedness_cannot_be_lost(){let mut s=model();s.vars[0].upper=None;s.objective=Expr{constant:q(0),terms:vec![(0,q(-1))]};let b=Block{steps:vec![],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::VarLower(0),Ref::VarInt(0),Ref::Exact]}};let c=Certificate{forward:b.clone(),reverse:b};verify(&s,&s,&c,&Limits::default()).unwrap();let mut t=s.clone();t.vars[0].upper=Some(q(0));assert!(verify(&s,&t,&c,&Limits::default()).is_err());}
#[test]fn infeasibility_requires_a_real_contradiction_in_both_directions(){let mut m=model();m.rows.push(Row{name:"impossible".into(),expr:Expr{constant:q(1),terms:vec![]},lower:None,upper:Some(q(0))});let b=Block{steps:vec![],end:End::Absurd{fact:Ref::RowUpper(0)}};let c=Certificate{forward:b.clone(),reverse:b};verify(&m,&m,&c,&Limits::default()).unwrap();assert!(verify(&m,&model(),&c,&Limits::default()).is_err());}
#[test]fn inequalities_can_use_equality_witnesses(){let m=model();let mut c=certificate();for b in [&mut c.forward,&mut c.reverse]{b.steps.push(Step::Lin{id:0,kind:Kind::Eq,constant:q(0),terms:vec![]});if let End::Return{checks,..}=&mut b.end{checks[3]=Ref::Local(0);}}verify(&m,&m,&c,&Limits::default()).unwrap();}
#[test]fn bytes_api_reports_only_fixed_guarantee(){let m=codec::encode_model(&model()).unwrap();let c=codec::encode_certificate(&certificate()).unwrap();let r=api::verify_bytes(&m,&m,&c,&Limits::default()).unwrap();assert_eq!(r["guarantee"],"MI_OPT");assert!(r.get("claims").is_none());assert!(api::verify_bytes(&m,&m,b"[]",&Limits::default()).is_err());}
